const { until } = require('selenium-webdriver');

class BasePage {
    constructor(driver) {
        this.driver = driver;
    }

    async click(element) {
        await this.driver.wait(until.elementIsVisible(element), 10000);
        await element.click();
    }

    async type(element, text) {
        await this.driver.wait(until.elementIsVisible(element), 10000);
        await element.sendKeys(text);
    }
}
module.exports = BasePage;

const { By } = require('selenium-webdriver');
const BasePage = require('./BasePage');

class LoginPage extends BasePage {
    get mobileInput() { return this.driver.findElement(By.id('mobile')); }
    get passwordInput() { return this.driver.findElement(By.id('password')); }
    get loginButton() { return this.driver.findElement(By.id('login-btn')); }

    async login(mobile, password) {
        await this.type(this.mobileInput, mobile);
        await this.type(this.passwordInput, password);
        await this.click(this.loginButton);
    }
}
module.exports = LoginPage;

const { By, until } = require('selenium-webdriver');
const BasePage = require('./BasePage');

class UserManagementPage extends BasePage {
    get navUserMgmt() { return this.driver.findElement(By.linkText('User Management')); }
    get btnAddInvite() { return this.driver.findElement(By.id('add-invite-btn')); }
    get nameField() { return this.driver.findElement(By.id('user-name')); }
    get emailField() { return this.driver.findElement(By.id('user-email')); }
    get btnSendInvite() { return this.driver.findElement(By.id('send-invite-btn')); }
    get successMsg() { return this.driver.findElement(By.className('success-toast')); }

    async inviteUser(name, email) {
        await this.click(this.navUserMgmt);
        await this.click(this.btnAddInvite);
        await this.type(this.nameField, name);
        await this.type(this.emailField, email);
        await this.click(this.btnSendInvite);
    }
