const { Builder } = require('selenium-webdriver');
const { expect } = require('chai');
const LoginPage = require('../pages/LoginPage');
const UserManagementPage = require('../pages/UserManagementPage');
const GridPage = require('../pages/GridPage');

describe('Team and Grid Management Suite', function() {
    let driver;
    let loginPage;
    let userPage;
    let gridPage;

    before(async () => {
        driver = await new Builder().forBrowser('chrome').build();
        loginPage = new LoginPage(driver);
        userPage = new UserManagementPage(driver);
        gridPage = new GridPage(driver);
        await driver.get(process.env.APP_URL);
    });

    after(async () => { await driver.quit(); });

    it('TC-TS-AI-2488-01: Happy Path - Add and Invite Team Member', async () => {
        await loginPage.login(process.env.USER_MOBILE, process.env.USER_PASSWORD);
        await userPage.inviteUser('John Doe', 'john.doe@example.com');
        const isDisplayed = await userPage.successMsg.isDisplayed();
        expect(isDisplayed).to.be.true;
    });

    it('TC-US001-02: Verify pagination dynamic load', async () => {
        // Ensure we are on the grid view (assuming navigation or state persist)
        const initialPage = await gridPage.getCurrentPageNumber();

        await gridPage.navigateToNextPage();

        const finalPage = await gridPage.getCurrentPageNumber();
        expect(finalPage).to.equal(initialPage + 1);

        // Verify grid dynamic update - generic check for visibility
        const rows = await gridPage.gridRows;
        expect(rows.length).to.be.greaterThan(0);
    });
});

const { By } = require('selenium-webdriver');
const BasePage = require('./BasePage');

class GridPage extends BasePage {
    get nextButton() { return this.driver.findElement(By.id('next-pagination-btn')); }
    get currentPageIndicator() { return this.driver.findElement(By.className('active-page')); }
    get gridRows() { return this.driver.findElements(By.css('.grid-row')); }

    async navigateToNextPage() {
        await this.click(this.nextButton);
    }

    async getCurrentPageNumber() {
        const text = await this.currentPageIndicator.getText();
        return parseInt(text, 10);
    }
}
module.exports = GridPage;

