---

### --- Page Object Model (POM)

#### `pages/BasePage.ts`
```typescript
import { expect, Locator, Page } from '@playwright/test';

/**
 * Abstract Base Page providing common web utilities and wrapper actions.
 */
export abstract class BasePage {
  public readonly page: Page;

  /**
   * @param page Playwright Page instance
   */
  constructor(page: Page) {
    this.page = page;
  }

  /**
   * Navigates directly to a specified relative path or complete URL.
   * @param path Target path
   */
  public async navigateTo(path: string = ''): Promise<void> {
    await this.page.goto(path, { waitUntil: 'domcontentloaded' });
  }

  /**
   * Safely gets the inner text content from a locator.
   * @param locator Playwright Locator
   */
  public async getText(locator: Locator): Promise<string> {
    return (await locator.textContent()) || '';
  }

  /**
   * Explicitly waits until a given locator is enabled.
   * @param locator Target Locator
   * @param timeout Optional explicit timeout
   */
  public async waitForEnabled(locator: Locator, timeout?: number): Promise<void> {
    await expect(locator).toBeEnabled({ timeout: timeout ?? 10000 });
  }

  /**
   * Fills an input field after ensuring visibility.
   * @param locator Target input locator
   * @param value Text value to input
   */
  public async fillInput(locator: Locator, value: string): Promise<void> {
    await locator.waitFor({ state: 'visible' });
    await locator.fill(value);
  }

  /**
   * Clicks a target element after waiting for interactivity.
   * @param locator Target locator
   */
  public async clickElement(locator: Locator): Promise<void> {
    await locator.waitFor({ state: 'visible' });
    await locator.click();
  }
}
```

#### `pages/UserManagementPage.ts`
```typescript
import { expect, Locator, Page } from '@playwright/test';
import { BasePage } from './BasePage';

/**
 * Page Object encapsulating elements and actions for the User Management section.
 */
export class UserManagementPage extends BasePage {
  // Locators following Priority Strategy: Role -> TestId -> Label -> CSS
  public readonly leftMenuUserManagementLink: Locator;
  public readonly pageHeader: Locator;
  public readonly usernameInput: Locator;
  public readonly submitButton: Locator;
  public readonly validationErrorMessage: Locator;
  public readonly successNotification: Locator;

  constructor(page: Page) {
    super(page);
    this.leftMenuUserManagementLink = page.getByRole('link', { name: 'User Management' });
    this.pageHeader = page.getByRole('heading', { name: 'User Management' });
    this.usernameInput = page.getByLabel('User Name');
    this.submitButton = page.getByRole('button', { name: 'Submit' });
    this.validationErrorMessage = page.getByTestId('validation-error');
    this.successNotification = page.getByTestId('success-alert');
  }

  /**
   * Navigates to the User Management feature using the left navigation menu.
   */
  public async clickUserManagementMenu(): Promise<void> {
    await this.clickElement(this.leftMenuUserManagementLink);
  }

  /**
   * Performs form submission in the User Management module.
   * @param username User input string
   */
  public async submitUserForm(username: string): Promise<void> {
    await this.fillInput(this.usernameInput, username);
    await this.clickElement(this.submitButton);
  }

  /**
   * Clears input and attempts to trigger validation errors.
   */
  public async submitEmptyForm(): Promise<void> {
    await this.usernameInput.clear();
    await this.clickElement(this.submitButton);
  }

  /**
   * Returns validation error message text.
   */
  public async getErrorMessageText(): Promise<string> {
    await this.validationErrorMessage.waitFor({ state: 'visible' });
    return await this.getText(this.validationErrorMessage);
  }
}
```

---

### --- Test Implementation

#### `tests/user-management.spec.ts`
```typescript
import { test, expect, Page } from '@playwright/test';
import { UserManagementPage } from '../pages/UserManagementPage';
import { EnvUtils } from '../utils/envUtils';

test.describe('User Management Module Automation', () => {
  let userManagementPage: UserManagementPage;

  test.beforeEach(async ({ page }) => {
    userManagementPage = new UserManagementPage(page);
    await page.goto(EnvUtils.BASE_URL);
  });

  test('TC-TS-US-002-01-001: Verify happy path execution for Verify Navigation to User Management', async ({ page }, testInfo) => {
    // Step 1: Navigate to the application target module via menu
    await userManagementPage.clickUserManagementMenu();

    // Step 2: Verify successfully navigated to the feature page
    await expect(userManagementPage.pageHeader).toBeVisible();

    // Step 3: Perform Primary Input Action & Submit Form
    await userManagementPage.submitUserForm('StandardValidUser');

    // Step 4: Verify successful completion
    await expect(userManagementPage.successNotification).toBeVisible();
  });

  test('TC-TS-US-002-01-002: Verify negative error handling for Verify Navigation to User Management', async ({ page }, testInfo) => {
    // Step 1: Navigate to target feature
    await userManagementPage.clickUserManagementMenu();
    await expect(userManagementPage.pageHeader).toBeVisible();

    // Step 2: Enter invalid or empty inputs into required fields
    await userManagementPage.submitEmptyForm();

    // Step 3: Verify appropriate error message and input validation alerts are displayed
    const errorMessage = await userManagementPage.getErrorMessageText();
    expect(errorMessage).not.toBe('');
    await expect(userManagementPage.validationErrorMessage).toBeVisible();
  });
});
```

